    {"상황": "신앙의 형식은 갖추었으나 내면은 공허한 성도", "성경원리": "진리를 행하지 않는 고백은 공허하다. 참된 교제는 내면의 변화를 수반한다. 형식적 종교가 아니라 실질적 관계가 필요하다", "실제적용": "종교적 활동을 줄이더라도 하나님과의 진실한 만남에 집중하도록 안내하라. 기도 속에서 자신의 진짜 모습을 하나님 앞에 내려놓는 훈련을 시작하라"}
