    {"항목": "구약의 하나님을 아는 지식", "내용": "구약에서 하나님을 아는 것은 단순한 정보가 아니라 언약 관계를 의미했다. 호세아는 내 백성이 지식이 없으므로 망하는도다(호 4:6)라고 탄식했고 예레미야는 나를 아는 것이 마음에 있으리라(렘 31:33-34)고 예언했다", "목회적활용": "하나님을 안다는 것이 무엇인지 구체적으로 가르치라. 그것은 교리적 지식을 넘어 삶의 순종으로 나타나는 관계적 앎이다"}
