    {"구분": "요셉을 미워한 형들", "내용": "요셉의 형들은 동생을 미워하여 구덩이에 던지고 종으로 팔았다(창 37장). 그러나 결국 요셉은 형들을 용서하고 구원했다", "그리스도연결": "미워하는 자를 사랑으로 구원하시는 그리스도의 예표이다. 형들의 미움은 어둠이었지만 요셉의 용서는 빛이었다"}
