    {"대지": "서론", "내용": "요한은 빛과 어둠을 판별하는 구체적 기준을 제시한다. 그것은 형제 사랑이다. 아무리 경건한 언어로 신앙을 고백해도 형제를 미워하면 어둠 가운데 있는 것이다", "예화_적용": "체온계는 건강을 만들지 못하지만 건강 상태를 정확히 보여준다. 형제에 대한 태도는 영적 상태의 정확한 체온계이다"},
    {"대지": "1대지: 빛 가운데 있다 하며 (고백)", "내용": "빛 가운데 있다는 고백은 아름다운 것이다. 그러나 고백만으로는 충분하지 않다. 고백은 삶으로 뒷받침되어야 한다", "예화_적용": "자격증을 벽에 걸어놓았다고 전문가가 되는 것이 아니다. 실력이 증명해야 한다"},
    {"대지": "2대지: 형제를 미워하는 자 (현실)", "내용": "형제를 미워하는 것은 사랑의 계명에 대한 정면 위반이다. 미움은 작은 감정이 아니라 영적 상태를 보여주는 심각한 증상이다", "예화_적용": "열이 나는 것은 몸에 감염이 있다는 신호이듯 미움은 영혼에 어둠이 있다는 신호이다"},
    {"대지": "3대지: 지금까지 어둠 가운데 (판정)", "내용": "지금까지라는 표현은 놀랍다. 형제를 미워하면서 빛을 주장하는 자는 한 번도 빛에 들어간 적이 없다는 의미이다. 이것은 심각한 경고이다", "예화_적용": "비행기 표를 샀다고 해도 탑승하지 않으면 여행을 한 적이 없는 것이다. 빛을 고백해도 사랑을 실천하지 않으면 빛에 들어간 적이 없다"},
    {"대지": "결론", "내용": "오늘 누군가를 미워하고 있는가. 그것은 단순한 감정 문제가 아니라 빛과 어둠의 문제이다. 미움을 내려놓고 형제를 사랑하는 것이 빛 가운데 거하는 길이다", "예화_적용": "어두운 방에서 나오려면 문을 열면 된다. 미움이라는 어둠에서 나오려면 사랑이라는 문을 열면 된다"}
