    {"새찬송가": "434", "통일찬송가": "330", "제목": "사랑의 하나님", "선정이유": "형제 사랑의 근원이신 하나님의 사랑을 고백하는 찬송이다"},
    {"새찬송가": "218", "통일찬송가": "327", "제목": "내 영혼에 햇빛 비치니", "선정이유": "어둠에서 빛으로 나아가는 영적 전환을 노래한다"}
