    {"새찬송가": "425", "통일찬송가": "299", "제목": "사랑은 언제나", "선정이유": "형제를 향한 지속적인 사랑의 실천을 노래한다"},
    {"새찬송가": "305", "통일찬송가": "287", "제목": "주 하나님 지으신 모든 세계", "선정이유": "하나님의 사랑 안에서 거리낌 없이 살아가는 자유를 찬양한다"}
