    {"새찬송가": "449", "통일찬송가": "335", "제목": "믿는 사람들은 주의 군사니", "선정이유": "적그리스도의 세력에 맞서 싸우는 영적 전사의 결단을 노래한다"},
    {"새찬송가": "551", "통일찬송가": "419", "제목": "선한 길로 날 택하시어", "선정이유": "마지막 때에 하나님의 인도하심을 따라가는 신앙을 고백한다"}
