    {"대지": "서론", "내용": "요한은 적그리스도가 교회 내부에서 나왔음을 밝힌다. 그들은 교회에 있었지만 진정으로 교회에 속한 자가 아니었다. 그들의 이탈이 이 사실을 드러냈다", "예화_적용": "태풍이 불면 뿌리 없는 나무가 쓰러진다. 시험이 오면 기초 없는 신앙이 무너진다"},
    {"대지": "1대지: 우리에게서 나감 (이탈)", "내용": "그들은 교회 공동체에서 나갔다. 이것은 충격적이지만 불가피한 것이었다. 속하지 않은 자가 결국 떠나는 것은 자연스러운 과정이다", "예화_적용": "껍질이 벗겨지면 속살이 드러나듯 시험이 오면 신앙의 속살이 드러난다"},
    {"대지": "2대지: 속한 자가 아님 (정체)", "내용": "물리적으로 교회에 있었어도 영적으로 속하지 않았다. 출석이 곧 소속이 아니다. 진정한 소속은 그리스도와의 생명적 연합이다", "예화_적용": "배에 타고 있다고 선원이 아니듯 교회에 있다고 그리스도에게 속한 것이 아니다"},
    {"대지": "3대지: 나타내려 함 (섭리)", "내용": "그들의 이탈은 하나님의 섭리적 과정이었다. 참과 거짓이 구별되어야 교회가 건강해진다. 이탈은 아픔이지만 정화의 과정이다", "예화_적용": "밀과 가라지가 분리되어야 참 수확이 이루어지듯 참과 거짓이 분리되어야 교회가 건강해진다"},
    {"대지": "결론", "내용": "교회를 떠나는 사람들 때문에 낙심하지 말라. 그들의 이탈은 진리가 작동하고 있다는 증거이다. 우리에게 중요한 것은 끝까지 그리스도 안에 거하는 것이다", "예화_적용": "강물이 흘러가도 바위는 제자리에 있다. 떠나는 자가 있어도 참된 자는 견고하게 남는다"}
