    {"새찬송가": "410", "통일찬송가": "306", "제목": "내 눈을 열어 주소서", "선정이유": "진리를 더 깊이 알기를 원하는 기도의 찬송이다"},
    {"새찬송가": "337", "통일찬송가": "454", "제목": "이 세상의 풍파 중에", "선정이유": "진리의 반석 위에 굳게 서서 거짓의 풍파를 이기는 것을 노래한다"}
