    {"새찬송가": "167", "통일찬송가": "162", "제목": "구주 예수 의의 태양", "선정이유": "재림하시는 의의 태양이신 그리스도를 기다리는 찬송이다"},
    {"새찬송가": "456", "통일찬송가": "342", "제목": "나의 갈길 다 가도록", "선정이유": "끝까지 주 안에 거하며 재림의 날까지 충성하겠다는 결단을 노래한다"}
