    {"항목": "2장의 결론과 3장으로의 전환", "내용": "29절은 2장의 결론이면서 3장의 하나님의 자녀 주제로의 전환점이다. 하나님에게서 난다는 개념이 3장 1절의 하나님의 자녀라 일컬음을 받으니로 자연스럽게 연결된다", "목회적활용": "하나님의 자녀됨과 의로운 삶의 연관성을 가르치라. 하나님의 자녀는 하나님의 성품인 의로움을 닮아간다"}
